const phone = ($json.phone || '').replace(/'/g, "''");
const key = ($json.key || '').replace(/'/g, "''");
const value = ($json.value || '').replace(/'/g, "''");
const channel = ($json.channel || 'sms').replace(/'/g, "''");

const SAFE_KEYS = ['service_interest','communication_preference','call_count',
  'last_call_date','channel_preference','preferred_contact_time','sentiment',
  'last_topic','call_intent','call_outcome','preferred_language','has_called_before','timezone'];

const tier = SAFE_KEYS.includes(key) ? 'safe' : 'protected';

const sql = \`INSERT INTO caller_memory (caller_phone, memory_key, memory_value, privacy_tier, source_channel, expires_at, updated_at)
VALUES ('\${phone}', '\${key}', '\${value}', '\${tier}', '\${channel}', NOW() + INTERVAL '90 days', NOW())
ON CONFLICT (caller_phone, memory_key) DO UPDATE SET
  memory_value = EXCLUDED.memory_value,
  privacy_tier = EXCLUDED.privacy_tier,
  expires_at = EXCLUDED.expires_at,
  updated_at = NOW()\`;

return [{ json: { sql } }];
